
"use client";

import { useMemo, useState } from "react";

type Produto = {
  id: number;
  nome: string;
  descricao: string;
  categoria: string;
  preco: number;
  estoque: number;
};

type Pedido = {
  id: string;
  cliente: string;
  data: string;
  status: string;
  total: number;
};

const produtosIniciais: Produto[] = [
  { id: 1, nome: "Red Velvet", descricao: "Bolo clássico e irresistível", categoria: "Bolos", preco: 89.9, estoque: 12 },
  { id: 2, nome: "Chocolate com Morango", descricao: "Bolo de chocolate com morangos", categoria: "Bolos", preco: 79.9, estoque: 8 },
  { id: 3, nome: "Cupcake de Baunilha", descricao: "Com cobertura de creme", categoria: "Cupcakes", preco: 12.9, estoque: 25 },
  { id: 4, nome: "Brownie", descricao: "Tradicional e muito macio", categoria: "Doces", preco: 9.9, estoque: 20 },
  { id: 5, nome: "Torta de Limão", descricao: "Cremosa e refrescante", categoria: "Tortas", preco: 69.9, estoque: 6 },
  { id: 6, nome: "Bolo de Cenoura", descricao: "Com cobertura de chocolate", categoria: "Bolos", preco: 59.9, estoque: 10 },
];

const pedidosIniciais: Pedido[] = [
  { id: "#00018", cliente: "Ana Clara Souza", data: "17/10/2026", status: "Entregue", total: 89.9 },
  { id: "#00017", cliente: "Mariana Lima", data: "16/10/2026", status: "Em preparo", total: 64.5 },
  { id: "#00016", cliente: "Juliana Alves", data: "15/10/2026", status: "Enviado", total: 129.9 },
  { id: "#00015", cliente: "Beatriz Costa", data: "14/10/2026", status: "Entregue", total: 72 },
];

const dinheiro = (valor: number) =>
  valor.toLocaleString("pt-BR", {
    style: "currency",
    currency: "BRL",
  });

export default function Home() {
  const [tela, setTela] = useState<"login" | "dashboard" | "produtos">("login");
  const [email, setEmail] = useState("");
  const [senha, setSenha] = useState("");
  const [nomeUsuario, setNomeUsuario] = useState("admin");
  const [busca, setBusca] = useState("");
  const [produtos, setProdutos] = useState<Produto[]>(produtosIniciais);
  const [pedidos] = useState<Pedido[]>(pedidosIniciais);
  const [modalAberto, setModalAberto] = useState(false);
  const [produtoEditando, setProdutoEditando] = useState<number | null>(null);
  const [visualizacao, setVisualizacao] = useState<Produto | null>(null);
  const [erro, setErro] = useState("");

  const produtoVazio: Produto = {
    id: 0,
    nome: "",
    descricao: "",
    categoria: "Bolos",
    preco: 0,
    estoque: 0,
  };

  const [formProduto, setFormProduto] = useState<Produto>(produtoVazio);

  const produtosFiltrados = useMemo(() => {
    const termo = busca.toLowerCase().trim();

    return produtos.filter((produto) =>
      `${produto.nome} ${produto.categoria} ${produto.descricao}`
        .toLowerCase()
        .includes(termo)
    );
  }, [produtos, busca]);

  const totalVendas = pedidos.reduce((total, pedido) => total + pedido.total, 0);

  function entrar(event: React.FormEvent<HTMLFormElement>) {
    event.preventDefault();

    if (!email.trim() || !senha.trim()) {
      setErro("Preencha o e-mail e a senha para continuar.");
      return;
    }

    setNomeUsuario(email.split("@")[0] || "admin");
    setErro("");
    setTela("dashboard");
  }

  function abrirNovoProduto() {
    setProdutoEditando(null);
    setFormProduto({
      ...produtoVazio,
      id: Date.now(),
    });
    setModalAberto(true);
  }

  function abrirEdicao(produto: Produto) {
    setProdutoEditando(produto.id);
    setFormProduto({ ...produto });
    setModalAberto(true);
  }

  function salvarProduto(event: React.FormEvent<HTMLFormElement>) {
    event.preventDefault();

    if (!formProduto.nome.trim() || formProduto.preco <= 0 || formProduto.estoque < 0) {
      alert("Informe o nome, um preço maior que zero e um estoque válido.");
      return;
    }

    if (produtoEditando !== null) {
      setProdutos((lista) =>
        lista.map((produto) =>
          produto.id === produtoEditando ? { ...formProduto } : produto
        )
      );
    } else {
      setProdutos((lista) => [...lista, { ...formProduto, id: Date.now() }]);
    }

    setModalAberto(false);
  }

  function excluirProduto(id: number) {
    const confirmar = window.confirm("Deseja realmente excluir este produto?");

    if (confirmar) {
      setProdutos((lista) => lista.filter((produto) => produto.id !== id));
      setVisualizacao(null);
    }
  }

  function navegar(destino: "dashboard" | "produtos") {
    setTela(destino);
    setBusca("");
  }

  if (tela === "login") {
    return (
      <main className="login-page">
        <section className="login-card">
          <div className="brand-icon">♕</div>
          <h1 className="brand">Velvet Dreams</h1>
          <p className="brand-subtitle">♥ Confeitaria artesanal ♥</p>

          <p className="login-description">
            Adoce seus melhores momentos.
          </p>

          <form onSubmit={entrar}>
            <div className="field">
              <label htmlFor="email">E-mail</label>
              <input
                id="email"
                type="email"
                placeholder="seuemail@exemplo.com"
                value={email}
                onChange={(event) => setEmail(event.target.value)}
                required
              />
            </div>

            <div className="field">
              <label htmlFor="senha">Senha</label>
              <input
                id="senha"
                type="password"
                placeholder="Digite sua senha"
                value={senha}
                onChange={(event) => setSenha(event.target.value)}
                required
              />
            </div>

            {erro && <p role="alert" style={{ color: "#a52d46" }}>{erro}</p>}

            <button className="primary-button login-button" type="submit">
              Entrar 
            </button>
          </form>

          <p className="login-note">
            Um toque de carinho em cada detalhe.
          </p>
        </section>
      </main>
    );
  }

  return (
    <div className="app-layout">
      <aside className="sidebar">
        <div className="brand-icon">♕</div>
        <h2 className="brand">Velvet Dreams</h2>
        <span className="brand-subtitle">♥ Confeitaria artesanal ♥</span>

        <nav className="sidebar-nav" aria-label="Menu principal">
          <button
            className={`nav-button ${tela === "dashboard" ? "active" : ""}`}
            onClick={() => navegar("dashboard")}
          >
            <span>⌂</span> Dashboard
          </button>

          <button
            className={`nav-button ${tela === "produtos" ? "active" : ""}`}
            onClick={() => navegar("produtos")}
          >
            <span>♧</span> Produtos
          </button>

          <button
            className="nav-button"
            onClick={() => document.getElementById("pedidos")?.scrollIntoView({ behavior: "smooth" })}
          >
            <span>▤</span> Pedidos
          </button>

          <button
            className="nav-button"
            onClick={() => alert("Área de clientes: em breve!")}
          >
            <span>♙</span> Clientes
          </button>

          <button
            className="nav-button"
            onClick={() => alert(`Total de vendas dos pedidos: ${dinheiro(totalVendas)}`)}
          >
            <span>▥</span> Relatórios
          </button>
        </nav>

        <div className="sidebar-bottom">
          <button
            className="nav-button"
            onClick={() => {
              setTela("login");
              setSenha("");
              setErro("");
            }}
          >
            ↪ Sair
          </button>
        </div>
      </aside>

      <main className="main-area">
        <header className="topbar">
          <input
            className="search-input"
            type="search"
            placeholder={tela === "produtos" ? "Buscar produto..." : "Buscar..."}
            value={busca}
            onChange={(event) => setBusca(event.target.value)}
            aria-label="Buscar"
          />
          <span className="admin-label">♙ {nomeUsuario}</span>
        </header>

        {tela === "dashboard" ? (
          <>
            <div className="page-heading">
              <div>
                <h1>Olá, {nomeUsuario}! ♥</h1>
                <p>Bem-vindo ao seu painel de controle.</p>
              </div>
              <span style={{ fontFamily: "Playfair Display, serif", fontStyle: "italic" }}>
                Grandes sonhos também são feitos de doce!
              </span>
            </div>

            <section className="stats-grid">
              <article className="stat-card">
                <div className="stat-icon">♧</div>
                <p className="stat-label">Total de Produtos</p>
                <p className="stat-value">{produtos.length}</p>
                <button className="stat-link" onClick={() => navegar("produtos")}>
                  Ver produtos →
                </button>
              </article>

              <article className="stat-card">
                <div className="stat-icon">▣</div>
                <p className="stat-label">Total de Pedidos</p>
                <p className="stat-value">{pedidos.length}</p>
                <button
                  className="stat-link"
                  onClick={() => document.getElementById("pedidos")?.scrollIntoView({ behavior: "smooth" })}
                >
                  Ver pedidos →
                </button>
              </article>

              <article className="stat-card">
                <div className="stat-icon">R$</div>
                <p className="stat-label">Vendas dos pedidos</p>
                <p className="stat-value">{dinheiro(totalVendas)}</p>
                <button
                  className="stat-link"
                  onClick={() => alert("Este valor é a soma dos pedidos de exemplo.")}
                >
                  Ver vendas →
                </button>
              </article>
            </section>

            <section className="panel" id="pedidos">
              <div className="panel-heading">
                <h2>Pedidos recentes</h2>
                <span style={{ fontSize: 12, color: "#781d32" }}>
                  {pedidos.length} pedidos
                </span>
              </div>

              <div className="table-wrapper">
                <table>
                  <thead>
                    <tr>
                      <th>Nº Pedido</th>
                      <th>Cliente</th>
                      <th>Data</th>
                      <th>Status</th>
                      <th>Total</th>
                    </tr>
                  </thead>
                  <tbody>
                    {pedidos.map((pedido) => (
                      <tr key={pedido.id}>
                        <td>{pedido.id}</td>
                        <td>{pedido.cliente}</td>
                        <td>{pedido.data}</td>
                        <td>
                          <span className="status">{pedido.status}</span>
                        </td>
                        <td>{dinheiro(pedido.total)}</td>
                      </tr>
                    ))}
                  </tbody>
                </table>
              </div>
            </section>

            <section className="footer-note">
              <div className="footer-note-inner">
                <h3>Gerencie seus produtos ♥</h3>
                <p>Adicione, edite e visualize os doces da sua confeitaria.</p>
                <button
                  className="primary-button"
                  onClick={() => navegar("produtos")}
                >
                  Ver produtos →
                </button>
              </div>
            </section>
          </>
        ) : (
          <>
            <div className="page-heading">
              <div>
                <h1>Produtos</h1>
                <p>Gerencie todos os produtos da sua confeitaria.</p>
              </div>

              <button className="primary-button" onClick={abrirNovoProduto}>
                + Novo produto
              </button>
            </div>

            <section className="panel">
              <div className="panel-heading">
                <h2>Lista de produtos</h2>
                <span style={{ color: "#896b71", fontSize: 13 }}>
                  {produtosFiltrados.length} produto(s)
                </span>
              </div>

              <div className="table-wrapper">
                <table>
                  <thead>
                    <tr>
                      <th>Imagem</th>
                      <th>Nome</th>
                      <th>Categoria</th>
                      <th>Preço</th>
                      <th>Estoque</th>
                      <th>Status</th>
                      <th>Ações</th>
                    </tr>
                  </thead>
                  <tbody>
                    {produtosFiltrados.map((produto) => (
                      <tr key={produto.id}>
                        <td>
                          <div className="product-placeholder" aria-label="Ilustração de doce">
                            ♧
                          </div>
                        </td>
                        <td>
                          <div className="product-name">{produto.nome}</div>
                          <div className="product-description">{produto.descricao}</div>
                        </td>
                        <td>{produto.categoria}</td>
                        <td>{dinheiro(produto.preco)}</td>
                        <td>{produto.estoque}</td>
                        <td>
                          <span className={`status ${produto.estoque < 8 ? "low" : ""}`}>
                            {produto.estoque < 8 ? "Estoque baixo" : "Ativo"}
                          </span>
                        </td>
                        <td>
                          <div className="table-actions">
                            <button
                              className="small-button"
                              title="Editar produto"
                              aria-label={`Editar ${produto.nome}`}
                              onClick={() => abrirEdicao(produto)}
                            >
                              ✎
                            </button>
                            <button
                              className="small-button"
                              title="Visualizar produto"
                              aria-label={`Visualizar ${produto.nome}`}
                              onClick={() => setVisualizacao(produto)}
                            >
                              ◉
                            </button>
                            <button
                              className="small-button"
                              title="Excluir produto"
                              aria-label={`Excluir ${produto.nome}`}
                              onClick={() => excluirProduto(produto.id)}
                            >
                              ♲
                            </button>
                          </div>
                        </td>
                      </tr>
                    ))}
                  </tbody>
                </table>

                {produtosFiltrados.length === 0 && (
                  <div className="empty-state">
                    Nenhum produto encontrado. Tente outra busca!
                  </div>
                )}
              </div>
            </section>

            <button
              className="secondary-button"
              onClick={() => navegar("dashboard")}
            >
              ← Voltar ao dashboard
            </button>
          </>
        )}
      </main>

      {modalAberto && (
        <div className="modal-backdrop">
          <section className="modal" role="dialog" aria-modal="true" aria-labelledby="modal-titulo">
            <h2 id="modal-titulo">
              {produtoEditando !== null ? "Editar produto" : "Novo produto"} ♥
            </h2>

            <form onSubmit={salvarProduto}>
              <div className="field">
                <label htmlFor="nome-produto">Nome</label>
                <input
                  id="nome-produto"
                  value={formProduto.nome}
                  onChange={(event) =>
                    setFormProduto({ ...formProduto, nome: event.target.value })
                  }
                  required
                />
              </div>

              <div className="field">
                <label htmlFor="descricao-produto">Descrição</label>
                <input
                  id="descricao-produto"
                  value={formProduto.descricao}
                  onChange={(event) =>
                    setFormProduto({ ...formProduto, descricao: event.target.value })
                  }
                />
              </div>

              <div className="field">
                <label htmlFor="categoria-produto">Categoria</label>
                <select
                  id="categoria-produto"
                  value={formProduto.categoria}
                  onChange={(event) =>
                    setFormProduto({ ...formProduto, categoria: event.target.value })
                  }
                >
                  <option>Bolos</option>
                  <option>Cupcakes</option>
                  <option>Doces</option>
                  <option>Tortas</option>
                </select>
              </div>

              <div className="field">
                <label htmlFor="preco-produto">Preço (R$)</label>
                <input
                  id="preco-produto"
                  type="number"
                  min="0.01"
                  step="0.01"
                  value={formProduto.preco || ""}
                  onChange={(event) =>
                    setFormProduto({
                      ...formProduto,
                      preco: Number(event.target.value),
                    })
                  }
                  required
                />
              </div>

              <div className="field">
                <label htmlFor="estoque-produto">Estoque</label>
                <input
                  id="estoque-produto"
                  type="number"
                  min="0"
                  step="1"
                  value={formProduto.estoque}
                  onChange={(event) =>
                    setFormProduto({
                      ...formProduto,
                      estoque: Number(event.target.value),
                    })
                  }
                  required
                />
              </div>

              <div className="modal-actions">
                <button
                  type="button"
                  className="secondary-button"
                  onClick={() => setModalAberto(false)}
                >
                  Cancelar
                </button>
                <button type="submit" className="primary-button">
                  Salvar produto
                </button>
              </div>
            </form>
          </section>
        </div>
      )}

      {visualizacao && (
        <div className="modal-backdrop" onClick={() => setVisualizacao(null)}>
          <section
            className="modal"
            role="dialog"
            aria-modal="true"
            aria-labelledby="visualizacao-titulo"
            onClick={(event) => event.stopPropagation()}
          >
            <div className="product-placeholder" style={{ width: "100%", height: 110 }}>
              ♧
            </div>
            <h2 id="visualizacao-titulo">{visualizacao.nome}</h2>
            <p>{visualizacao.descricao}</p>
            <p><strong>Categoria:</strong> {visualizacao.categoria}</p>
            <p><strong>Preço:</strong> {dinheiro(visualizacao.preco)}</p>
            <p><strong>Estoque:</strong> {visualizacao.estoque} unidade(s)</p>
            <button
              className="primary-button"
              onClick={() => setVisualizacao(null)}
            >
              Fechar
            </button>
          </section>
        </div>
      )}
    </div>
  );
}
